import json
from pathlib import Path
R=Path(__file__).resolve().parents[2];data=json.loads((R/'data/americas.json').read_text());c=json.loads((R/'research/americas-coverage.json').read_text());new=[];rr={};nn={}
def a(y,n,d,t,s,st,why,sol=None,note=None):
 rr.setdefault(y,{})[str(n)]=d;nn.setdefault(y,{})[str(n)]=why
 if not 4<=d<=7:return
 u=f'https://cms.math.ca/wp-content/uploads/2019/07/sol{y}.pdf'
 new.append(dict(id=f'ca-cmo-{y}-{n}',country='Canada',competition='CMO',year=y,section='National final',number=str(n),statement=st,solution=sol or f'[Read the official worked solution, Problem {n}]({u}).',sourceUrl=f'https://cms.math.ca/wp-content/uploads/2019/07/exam{y}.pdf',solutionUrl=u,solutionKind='original-exposition' if sol else 'source-link',topic=t,tags=s,subtopics=s,difficulty=d,ratingReason=why,reviewStatus='individually-assessed',notes=note or 'Statement restated in original wording. Official CMS solution reviewed.'))
a(2003,1,3,'Algebra',[],None,'The relative clock-hand angle is 11m/2 degrees; solve 11m≡±2 modulo 720 in the stated interval.')
a(2003,2,4,'Number Theory',['Modular arithmetic','Multiplicative order'],r'Find the final three decimal digits of $2003^{\,2002^{2001}}$.','Reduce the base modulo 1000, establish 3^100≡1, and reduce the inner exponent modulo 100 using modulo 25 and parity. A final truncated binomial expansion gives 241.')
a(2003,3,2.5,'Algebra',[],None,'The cubic equation forces one variable below 1 unless all equal 1; then the other two squares exceed the product by AM–GM.')
a(2003,4,4,'Geometry',['Similarity & congruence','Circles & tangency'],r'Three distinct circles have the same chord $AB$. A variable line through $A$, other than $AB$, meets them again at $X,Y,Z$, labelled with $Y$ between $X,Z$. Prove that $XY/YZ$ does not depend on the line.','Project the three collinear centres onto the variable line. Their projections are the midpoints of AX,AY,AZ, so the desired ratio equals the fixed ratio between consecutive centres.')
a(2003,5,6,'Geometry',['Combinatorial geometry','Algorithms & constructions'],r'A set of $n$ plane points has all pairwise distances at least 1. Prove that it contains at least $n/7$ points whose pairwise distances are at least $\sqrt3$.','Greedily choose a highest remaining point. Its nearby lower half-annulus splits into six 30-degree sectors of diameter less than 1; at most six neighbours are removed with each selection.')
a(2002,1,4,'Combinatorics',['Pigeonhole principle','Sets & partitions'],r'Find the largest size of a subset of $\{1,2,\ldots,9\}$ whose sums over unordered pairs of distinct elements are all different.','Six elements would give 15 sums filling the entire interval 3 to 17. Both endpoint pairs would then be forced, producing the collision 1+9=2+8; a five-element construction completes the argument.')
a(2002,2,4.5,'Number Theory',['Divisibility & GCD','Algorithms & constructions'],r'Call $n\ge1$ practical if each integer from 1 to $n$ is a sum of distinct positive divisors of $n$. Prove that the product of two practical integers is practical.','Write k=aq+b using one factor q, then represent a and b using divisors of the factors. Multiplying the first representation by q keeps its divisors disjoint from those in the remainder because the latter are strictly smaller than q.')
a(2002,3,3.5,'Algebra',[],None,'After multiplying by abc, two standard symmetric AM–GM steps show sum a⁴≥sum a²bc; equality is a=b=c.')
a(2002,4,5,'Geometry',['Angles & cyclic quadrilaterals','Similarity & congruence'],r'Points $A,B$ lie on a circle of radius $r$, with $AB<\sqrt3r$. The circle centred at $B$ of radius $AB$ meets the first circle again at $C$. Let $P$ be the third vertex of the equilateral triangle on $AB$ inside the first circle, and let $CP$ meet it again at $Q$. Prove $PQ=r$.','The auxiliary circle centred at B gives a 30-degree inscribed angle, hence AQ=r. A second angle chase makes triangle APQ isosceles, so PQ=AQ.')
a(2002,5,5.5,'Algebra',['Functional equations','Extremal arguments'],r'Classify functions $f:\mathbb Z_{\ge0}\to\mathbb Z_{\ge0}$ satisfying $xf(y)+yf(x)=(x+y)f(x^2+y^2)$ for all nonnegative integers $x,y$.','The equation makes f(x²+y²) a strict weighted mean when f(x) and f(y) differ. Choose a pair with minimum positive value difference to contradict integrality; first handle the zero input so both weights are positive.',sol=r'''Putting $y=0$ and $x>0$ gives $f(x^2)=f(0)$, in particular $f(1)=f(0)$. If $f$ is nonconstant, choose positive integers $u,v$ for which $0<f(v)-f(u)$ is as small as possible. Such positive indices exist because the value at 0 also occurs at 1. Then
$$f(u)<\frac{u f(v)+v f(u)}{u+v}=f(u^2+v^2)<f(v).$$
The middle value is an integer, contradicting minimality of the positive difference. Thus f is constant; every nonnegative integer constant indeed satisfies the equation.''',note='The original exposition supplies the zero-input check omitted from the shortest official minimal-difference proof.')
a(2001,1,4.5,'Number Theory',['Integer polynomials','Divisibility & GCD'],r'An integer-coefficient quadratic has distinct positive integer roots $R>J$ and a positive prime as the sum of its three coefficients. At some positive integer input it has value $-55$. Prove $J=2$ and determine $R$.','Evaluating a(x−R)(x−J) at 1 makes a product prime and forces the smaller root to be 2. Factoring −55 gives four cases, and primality of R−1 selects R=18.')
a(2001,2,6.5,'Combinatorics',['Probability','Counting','Extremal arguments'],r'The integer cells $-10,-9,\ldots,10$ are coloured red or white, and $n$ is the sum of the red labels. A token begins at 0 and makes ten independent fair steps of +1 or −1. If its probability of ending on red can be written $a/b$ with positive integers $a,b$ and $a+b=2001$, find the greatest possible $n$. Do not assume $a/b$ is reduced.','Translate the endpoint probabilities into binomial coefficients. The unreduced fraction permits eight candidate totals, requiring a constrained subset-sum analysis before optimizing which positive labels are red; the actual answer is 35, not the intended reduced-fraction answer 31.',note='The official report acknowledges that the coprime qualification was omitted from the question. This record preserves the printed unreduced interpretation and links the official extended analysis.')
a(2001,3,4.5,'Geometry',['Angles & cyclic quadrilaterals','Concurrency & collinearity'],r'In triangle $ABC$ with $AC>AB$, let $P$ be where the perpendicular bisector of $BC$ meets the internal bisector of $\angle A$. Let $X,Y$ be the perpendicular feet from $P$ to lines $AB,AC$, and put $Z=XY\cap BC$. Find $BZ/ZC$.','Recognize P as a circumcircle arc midpoint. Its pedal line is a Simson line, so Z is the midpoint of BC; alternatively congruent right triangles followed by Menelaus give the same ratio.')
a(2001,4,6.5,'Combinatorics',['Invariants','Algorithms & constructions'],r'Fix $n\ge1$. A rectangular table initially contains positive integers. A move either multiplies every entry of one row by $n$, or subtracts $n$ from every entry of one column. For which $n$ can every initial table be transformed to the all-zero table by finitely many moves?','Differences modulo n−1 rule out n≥3, with n=1 handled separately. For n=2, a carefully terminating row-doubling and column-subtraction procedure clears one column at a time while preserving earlier zero columns.')
a(2000,1,5,'Combinatorics',['Extremal arguments'],r'Three runners start together on a circular track of length 300 metres and each maintains a constant signed speed. Anne’s signed speed differs from each of the others. Prove that at some positive time she is at least 100 metres, measured along the shorter track arc, from each other runner.','Move to Anne’s frame and reflect either relative motion if necessary. When the two speed magnitudes are within a factor of two, a direct time works; otherwise the faster runner crosses a suitable arc while the slower remains in the middle third.')
a(2000,2,5,'Combinatorics',['Counting','Modular arithmetic','Permutations & arrangements'],r'How many permutations of $1901,1902,\ldots,2000$ have none of their nonempty initial sums divisible by 3?','After removing residue-zero terms, the nonzero residues are forced into one alternating pattern with an initial repeated 2. Choose the allowed zero positions and independently permute the numbers in each residue class.')
a(2000,3,6,'Combinatorics',['Pigeonhole principle','Algorithms & constructions'],r'Two thousand integers, each between $-1000$ and $1000$, have sum 1. Prove that some nonempty selection of them has sum zero.','Reorder the terms by always choosing a sign opposite the current partial sum. The total-sum condition guarantees a choice, and all 2000 nonzero partial sums lie among only 1999 possible integers, forcing repetition.')
a(2000,4,5.5,'Geometry',['Angles & cyclic quadrilaterals','Similarity & congruence'],r'A convex quadrilateral $ABCD$ satisfies $AB=CB$, $\angle CBD=2\angle ADB$, and $\angle ABD=2\angle CDB$. Prove $AD=CD$.','The two angle bisectors at B create a parallelogram. The angle-bisector theorem then shows its opposite side parallel AC, forcing BD through the midpoint of AC and yielding the required symmetry.')
a(2000,5,5.5,'Algebra',['Inequalities'],r'Reals $a_1\ge\cdots\ge a_{100}\ge0$ satisfy $a_1+a_2\le100$ and $a_3+\cdots+a_{100}\le100$. Find the maximum of $\sum a_i^2$ and all sequences attaining it.','Use a₁≤100−a₂ and the total sum ≤200 to rewrite the excess over 10000 as a sum of nonpositive products. Equality requires care when a₂=0; it gives the two distinct extremal sequences.')
a(1999,1,4,'Algebra',['Floors & fractional parts','Equations & systems'],r'Find every real $x$ satisfying $4x^2-40\lfloor x\rfloor+51=0$.','The inequalities x−1<floor(x)≤x bound x into two short intervals. Testing the six possible integer parts then finds exactly four roots; both bounds and the final floor checks are needed.')
a(1999,2,5,'Geometry',['Circles & tangency','Angles & cyclic quadrilaterals'],r'An equilateral triangle $ABC$ has altitude 1. A circle of radius 1 remains tangent to segment $AB$, with its centre on the same side of $AB$ as $C$, while its tangency point moves along $AB$. Show that the length of its circumference lying inside the triangle is constant.','The circle centre travels on the parallel through C. Reflection across that parallel and the 60-degree apex angle force the intercepted arc to subtend a fixed 30-degree inscribed angle; a coordinate chord calculation is an alternative.')
a(1999,3,5,'Number Theory',['Arithmetic functions','Squares & powers'],r'Let $d(n)$ be the number of positive divisors of $n$. Determine all positive integers satisfying $n=d(n)^2$.','The equation first makes n an odd square. Compare each prime-power factor p^β with 2β+1; equality can hold only for p=3,β=1, apart from the empty factorization n=1.')
a(1999,4,6,'Combinatorics',['Pigeonhole principle','Extremal arguments'],r'From any eight distinct numbers in $\{1,\ldots,17\}$, prove that some positive difference occurs for at least three ordered pairs. Give seven distinct numbers from this interval for which every positive difference occurs at most twice.','Combine seven consecutive gaps and six two-step gaps: their total is at most 46, whereas multiplicity at most two forces at least 49. The matching seven-element construction requires a separate verified difference list.')
a(1999,5,6,'Algebra',['Inequalities'],r'For $x,y,z\ge0$ with $x+y+z=1$, prove $x^2y+y^2z+z^2x\le4/27$ and find all equality cases.','Cyclic symmetry alone does not allow arbitrary sorting. First compare the two orientations to choose x≥y≥z, then transfer z into x without decreasing the expression; AM–GM solves the two-variable boundary case.')
a(1998,1,4.5,'Algebra',['Floors & fractional parts'],r'How many real numbers $a$ satisfy $\lfloor a/2\rfloor+\lfloor a/3\rfloor+\lfloor a/5\rfloor=a$?','The equation forces a to be integral. Writing a=30k+r cancels the linear contributions and gives exactly one integer k for each residue r=0,…,29, avoiding a large direct search.')
a(1998,2,4.5,'Algebra',['Equations & systems','Algebraic identities'],r'Solve $x=\sqrt{x-1/x}+\sqrt{1-1/x}$ over the real numbers.','After determining the radical domain, square once and multiply by x; a hidden completed square avoids a sixth-degree expansion. The remaining golden-ratio candidate must be checked in the original equation.')
a(1998,3,4,'Algebra',['Inequalities','Sequences & recurrences'],r'For every integer $n\ge2$, show $\frac1{n+1}\sum_{k=1}^n\frac1{2k-1}>\frac1n\sum_{k=1}^n\frac1{2k}$.','Separate the first odd reciprocal into two halves. Termwise comparison gives more than the even sum plus 1/2, and the even sum is less than n/2; the two bounds produce the required unequal denominators.')
a(1998,4,5.5,'Geometry',['Angles & cyclic quadrilaterals','Concurrency & collinearity'],r'Triangle $ABC$ has $\angle A=40^\circ$, $\angle B=60^\circ$. Choose $D\in AC$, $E\in AB$ with $\angle CBD=40^\circ$ and $\angle BCE=70^\circ$. If $F=BD\cap CE$, prove $AF\perp BC$.','An auxiliary equilateral triangle supplies two congruent triangles and forces BF=BC, which fixes the angle at C. Alternatively trigonometric Ceva reduces the concurrence to a double-angle identity.')
a(1998,5,6.5,'Number Theory',['Descent','Diophantine equations','Sequences & recurrences'],r'Fix a positive integer $m$ and define $a_0=0,a_1=m,a_{n+1}=m^2a_n-a_{n-1}$. Prove that a nonnegative integer pair $a\le b$ solves $(a^2+b^2)/(ab+1)=m^2$ exactly when $(a,b)=(a_n,a_{n+1})$ for some $n\ge0$.','An invariant verifies all recurrence pairs. The converse requires Vieta descent: the other root m²a−b is a nonnegative integer smaller than a, and reversing the descent reconstructs the sequence.')
a(1997,1,4,'Number Theory',['Divisibility & GCD','Counting'],r'How many pairs of positive integers $x\le y$ satisfy $\gcd(x,y)=5!$ and $\operatorname{lcm}(x,y)=50!$?','For each of the 15 relevant primes, the two exponents must be the specified minimum and maximum, which differ. Independent assignments give 2^15 ordered pairs and symmetry halves the count.')
a(1997,2,4,'Combinatorics',['Combinatorial geometry','Algorithms & constructions'],r'A finite family of closed unit intervals has union $[0,50]$. Prove that 25 mutually disjoint intervals can be selected from the family.','Choose 25 test points spaced slightly more than 2 apart inside the interval. Any covering unit intervals containing them are pairwise disjoint, so no greedy endpoint complications are needed.')
a(1997,3,3.5,'Algebra',[],None,'Termwise comparison gives the telescoping lower bound. Compare each odd/even factor to the next even/odd factor, obtaining P²<1/1999<1/44².')
a(1997,4,5,'Geometry',['Transformations','Angles & cyclic quadrilaterals'],r'A point $O$ inside parallelogram $ABCD$ satisfies $\angle AOB+\angle COD=180^\circ$. Prove $\angle OBC=\angle ODC$.','Translate D to A and O to O′. The hypothesis makes AOBO′ cyclic; one circle-angle identity and the parallel translation vector give the requested equality.')
a(1997,5,5.5,'Algebra',['Sequences & recurrences','Algebraic identities'],r'Express $\sum_{k=0}^n\frac{(-1)^k\binom nk}{k^3+9k^2+26k+24}$ as a quotient of integer-coefficient polynomials in $n$.','Factor the cubic as (k+2)(k+3)(k+4), convert to binomial coefficients with top n+4, and complete the two alternating binomial sums. The omitted boundary terms leave 1/[2(n+3)(n+4)].')
a(1996,1,3,'Algebra',[],None,'Combine the three rational root expressions over their product denominator, then apply Vieta and f(1)=−1 to obtain −7.')
a(1996,2,3.5,'Algebra',[],None,'Each cyclic equation is y=4x²/(1+4x²)≤x for nonnegative x; equality throughout gives 0 or 1/2.')
a(1996,3,6.5,'Combinatorics',['Permutations & arrangements','Recurrences & generating functions','Modular arithmetic'],r'Let $f(n)$ count permutations $(a_1,\ldots,a_n)$ of $1,\ldots,n$ with $a_1=1$ and $|a_i-a_{i+1}|\le2$ for all $i<n$. Is $f(1996)$ divisible by 3?','Classify permutations by the initial 2 or 3. The nonlocal constraint after a consecutive pair forces one exceptional alternating block, yielding f(n)=f(n−1)+f(n−3)+1; the recurrence has period 8 modulo 3.')
a(1996,4,5,'Geometry',['Similarity & congruence','Triangle geometry'],r'In isosceles triangle $ABC$ with $AB=AC$, the internal bisector from $B$ meets $AC$ at $D$. If $BC=BD+AD$, determine $\angle A$.','Mark BE=BD along BC so CE=AD. The angle-bisector ratio makes CED similar to CAB, revealing two isosceles triangles whose angle sum forces A=100 degrees.')
a(1996,5,4,'Number Theory',['Floors & fractional parts','Fractions & approximation'],r'Positive rational numbers $r_1,\ldots,r_m$ sum to 1. For positive integers $n$ define $f(n)=n-\sum_{k=1}^m\lfloor r_kn\rfloor$. Find its minimum and maximum.','The expression is an integer sum of fractional parts, so it lies from 0 to m−1. A common denominator attains zero, and one less attains m−1; m=1 is the immediate endpoint case.')
ids={x['id'] for x in new};data=[x for x in data if x['id'] not in ids]+new
(R/'data/americas.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
for y,rs in rr.items():
 c['fullyScreened']=[x for x in c['fullyScreened'] if not(x['competition']=='CMO' and x['year']==y)]
 c['partiallyScreened']=[x for x in c['partiallyScreened'] if not(x['competition']=='CMO' and x['year']==y)]
 r=dict(competition='CMO',year=y,ratings=rs,source=f'https://cms.math.ca/wp-content/uploads/2019/07/sol{y}.pdf',assessmentNotes=nn[y])
 if y==2001:
  r['pending']=['5'];r['note']='Held: for t=2sin(15°) or 2sin(75°), the odd-indexed circumcentre sequence makes four quarter-turn steps with ratio 1 and returns to its start. Thus P1=P1001=P2001 and the requested ratio x/y is 0/0. The official answer includes these values without addressing the degeneracy; no corrected statement silently substituted.'
  c['partiallyScreened'].append(r)
 else:c['fullyScreened'].append(r)
c['papersScreened']=len(c['fullyScreened']);c['problemAppearancesScreened']=sum(len(x['ratings']) for x in c['fullyScreened']+c['partiallyScreened']);c['uniqueIncluded']=len(data)
c['gaps'][0]='Canada: all CMO 1996–2026 questions reviewed except CMO 2001 Q5, held for an undefined 0/0 ratio in its published formulation. CMO 1969–1995 remains under review. All CJMO 2020–2026 fully screened.'
c['verificationNotes'].append('CMO 1996–2003: 39 questions individually assessed. CMO 2001 Q2 retains the officially acknowledged unreduced-fraction interpretation, whose maximum is 35 rather than 31. CMO 2001 Q5 held for a genuine periodic-orbit degeneracy making its requested distance ratio undefined. CMO 2002 Q5 independent solution supplies the missing positive-index justification in the minimal-difference argument.')
(R/'research/americas-coverage.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n');print(len(new),'new;',len(data),'total;',c['papersScreened'],'complete')
